from http.server import BaseHTTPRequestHandler, HTTPServer
from urllib.parse import urlparse, parse_qs
import json
RECORDS={1001:{'id':1001,'owner':'fictional-user-a','memo':'Demo schedule'},1002:{'id':1002,'owner':'fictional-user-b','memo':'Demo contact list'}}
class Handler(BaseHTTPRequestHandler):
 def do_GET(self):
  p=urlparse(self.path)
  if p.path!='/record': self.send_response(404); self.end_headers(); return
  try: rid=int(parse_qs(p.query).get('id',['0'])[0]); record=RECORDS[rid]; body=json.dumps(record).encode(); self.send_response(200)
  except Exception: body=b'{"error":"not found"}'; self.send_response(404)
  self.send_header('Content-Type','application/json'); self.send_header('Content-Length',str(len(body))); self.end_headers(); self.wfile.write(body)
 def log_message(self,*a): pass
HTTPServer(('127.0.0.1',8080),Handler).serve_forever()
